import { useCallback, useEffect, useRef, useState } from 'react'
import type { FormEvent, ReactNode } from 'react'
import { Activity, ArrowDownToLine, ArrowRight, ArrowUpRight, Beaker, BookOpen, Boxes, Check, CheckCheck, CheckCircle2, ChevronDown, ChevronRight, Circle, Clock3, Command, Cpu, FileCode2, FileSearch, FlaskConical, FolderGit2, GitBranch, GitCompareArrows, GitPullRequest, Layers3, ListFilter, LoaderCircle, LockKeyhole, Menu, Play, Plus, Radio, Search, Settings2, ShieldCheck, Sparkles, Square, Terminal, Unplug, X, XCircle } from 'lucide-react'
import { api, downloadArtifact, TOKEN_KEY } from './api'
import ComparisonPanel from './ComparisonPanel'
import BenchmarkReport from './BenchmarkReport'
import ReportExport from './ReportExport'
import { isVerified, verificationLimitations } from './verification'
import type { DetailTab, Diagnosis, Evidence, Health, Memory, Metrics, Patch, Project, Run, TestResult, TraceEvent, Verification, View } from './types'

const statusLabels: Record<string, string> = { queued: '排队中', investigating: '调查中', awaiting_approval: '待审批', verifying: '验证中', completed: '已完成', failed: '失败', rejected: '已拒绝', cancelled: '已取消' }
const modeLabels = { replay: '离线回放', live: '模型调查', investigate: '证据检索' }
const terminal = new Set(['completed', 'failed', 'rejected', 'cancelled'])
const time = (value?: string) => value ? new Date(value).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '—'
const date = (value?: string) => value ? new Date(value).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—'
const number = (value?: number) => value === undefined ? '—' : value.toLocaleString('zh-CN')
const errorMessage = (error: unknown) => error instanceof Error ? error.message : String(error)
function Badge({ status }: { status: string }) { return <span className={`status-badge status-${status}`}><span className="status-dot" />{statusLabels[status] || status}</span> }
function Empty({ icon, title, children, action }: { icon: ReactNode; title: string; children: ReactNode; action?: ReactNode }) { return <div className="empty-state"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{children}</p>{action}</div> }
function Loading({ label = '正在读取工作台…' }: { label?: string }) { return <div className="loading-state"><LoaderCircle className="spin" size={22}/><span>{label}</span></div> }
function PanelTitle({ icon, title, subtitle, right }: { icon?: ReactNode; title: string; subtitle?: string; right?: ReactNode }) { return <div className="panel-title"><div className="panel-title-copy">{icon}<div><h3>{title}</h3>{subtitle && <p>{subtitle}</p>}</div></div>{right}</div> }
function Modal({ title, subtitle, onClose, children, wide = false }: { title: string; subtitle: string; onClose: () => void; children: ReactNode; wide?: boolean }) {
  const dialog = useRef<HTMLDivElement>(null)
  useEffect(() => {
    const previouslyFocused = document.activeElement as HTMLElement | null
    const root = dialog.current;
    (root?.querySelector<HTMLElement>('input, select, textarea') || root?.querySelector<HTMLElement>('button'))?.focus()
    const key = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose()
      if (event.key === 'Tab' && root) {
        const items = [...root.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex="0"]')]
        const first = items[0]; const last = items[items.length - 1]
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus() }
        if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus() }
      }
    }
    document.addEventListener('keydown', key)
    return () => { document.removeEventListener('keydown', key); previouslyFocused?.focus() }
  }, [onClose])
  return <div className="modal-backdrop" onMouseDown={event => { if (event.target === event.currentTarget) onClose() }}><div ref={dialog} role="dialog" aria-modal="true" aria-label={title} className={`modal ${wide ? 'modal-wide' : ''}`}><header><div><span className="eyebrow">TRACEFORGE WORKSPACE</span><h2>{title}</h2><p>{subtitle}</p></div><button className="icon-button" onClick={onClose} aria-label="关闭"><X size={20}/></button></header>{children}</div></div>
}

export default function App() {
  const [view, setView] = useState<View>('runs')
  const [health, setHealth] = useState<Health | null>(null)
  const [projects, setProjects] = useState<Project[]>([])
  const [runs, setRuns] = useState<Run[]>([])
  const [metrics, setMetrics] = useState<Metrics | null>(null)
  const [selectedId, setSelectedId] = useState('')
  const [run, setRun] = useState<Run | null>(null)
  const [events, setEvents] = useState<TraceEvent[]>([])
  const [tab, setTab] = useState<DetailTab>('overview')
  const [filter, setFilter] = useState('all')
  const [search, setSearch] = useState('')
  const [loading, setLoading] = useState(true)
  const [detailLoading, setDetailLoading] = useState(false)
  const [error, setError] = useState('')
  const [connectionError, setConnectionError] = useState('')
  const [detailError, setDetailError] = useState('')
  const [busy, setBusy] = useState('')
  const [modal, setModal] = useState<'project' | 'run' | 'settings' | null>(null)
  const [mobileNav, setMobileNav] = useState(false)
  const [memoryProject, setMemoryProject] = useState('')
  const [memories, setMemories] = useState<Memory[]>([])
  const [extraLoading, setExtraLoading] = useState(false)
  const [evaluationType, setEvaluationType] = useState<'harness' | 'benchmark'>('harness')
  const [evaluation, setEvaluation] = useState<Record<string, unknown> | null>(null)
  const [refreshTick, setRefreshTick] = useState(0)
  const closeModal = useCallback(() => setModal(null), [])

  const refresh = useCallback(async () => {
    try {
      const [nextHealth, nextProjects, nextRuns, nextMetrics] = await Promise.all([api<Health>('/health'), api<Project[]>('/projects'), api<Run[]>('/runs'), api<Metrics>('/metrics')])
      setHealth(nextHealth); setProjects(nextProjects); setRuns(nextRuns); setMetrics(nextMetrics); setConnectionError('')
      setSelectedId(previous => previous && nextRuns.some(item => item.id === previous) ? previous : nextRuns[0]?.id || '')
      setMemoryProject(previous => previous || nextProjects[0]?.id || '')
    } catch (err) { setConnectionError(errorMessage(err)) }
    finally { setLoading(false) }
  }, [])
  useEffect(() => { void refresh(); const timer = window.setInterval(() => void refresh(), 5000); return () => window.clearInterval(timer) }, [refresh, refreshTick])
  useEffect(() => {
    if (!selectedId) { setRun(null); setEvents([]); return }
    let disposed = false
    setDetailLoading(true); setRun(null); setEvents([]); setDetailError('')
    const fetchRun = async () => {
      try {
        const [next, nextEvents] = await Promise.all([api<Run>(`/runs/${encodeURIComponent(selectedId)}`), api<TraceEvent[]>(`/runs/${encodeURIComponent(selectedId)}/events?after=0`)])
        if (!disposed) { setRun(next); setEvents(nextEvents); setDetailError('') }
      } catch (err) { if (!disposed) setDetailError(errorMessage(err)) }
      finally { if (!disposed) setDetailLoading(false) }
    }
    void fetchRun(); const timer = window.setInterval(() => void fetchRun(), 2200)
    return () => { disposed = true; window.clearInterval(timer) }
  }, [selectedId, refreshTick])
  useEffect(() => {
    let disposed = false
    if (view === 'memories' && !memoryProject) { setMemories([]); return }
    if (view !== 'memories' && view !== 'evaluation') return
    setExtraLoading(true)
    const promise = view === 'memories' ? api<Memory[]>(`/memories?project_id=${encodeURIComponent(memoryProject)}`).then(data => { if (!disposed) setMemories(data) }) : api<Record<string, unknown>>(evaluationType === 'harness' ? '/evaluation' : '/benchmarks/latest').then(data => { if (!disposed) setEvaluation(data) })
    promise.catch(err => { if (!disposed) { if (view === 'evaluation' && evaluationType === 'benchmark' && (err as { status?: number })?.status === 404) { setEvaluation({ available: false }); setError('') } else setError(errorMessage(err)) } }).finally(() => { if (!disposed) setExtraLoading(false) })
    return () => { disposed = true }
  }, [view, memoryProject, refreshTick, evaluationType])

  async function action(key: string, fn: () => Promise<unknown>) {
    setBusy(key); setError('')
    try { await fn(); await refresh() } catch (err) { setError(errorMessage(err)) } finally { setBusy('') }
  }
  const startDemo = () => action('demo', async () => { const data = await api<{ project: Project; run: Run }>('/demo', {}); setSelectedId(data.run.id); setView('runs'); setTab('overview') })
  const decide = (decision: 'approve' | 'reject') => {
    if (!run?.state.patch_digest) { setError('本次调查尚未生成可审批的补丁摘要，请等待状态更新。'); return }
    return action(decision, async () => { const next = await api<Run>(`/runs/${encodeURIComponent(run.id)}/approve`, { decision, patch_digest: run.state.patch_digest }); setRun(next); if (decision === 'approve') setTab('verification') })
  }
  const navigate = (next: View) => { setView(next); setMobileNav(false) }
  const openRun = (id: string) => { setSelectedId(id); setView('runs'); setTab('overview') }
  const selectedProject = projects.find(item => item.id === run?.project_id)
  const visibleRuns = runs.filter(item => (filter === 'all' || (filter === 'active' ? !terminal.has(item.status) : item.status === filter)) && (!search || `${item.title} ${item.id} ${projects.find(project => project.id === item.project_id)?.name || ''}`.toLowerCase().includes(search.toLowerCase())))
  const title = { runs: '调查工作台', projects: '项目注册表', memories: '知识记忆', evaluation: '评测中心', compare: '运行对比' }[view]
  const subtitle = { runs: '从线索到验证，每一步都有证据。', projects: '连接代码仓库，定义可信的执行边界。', memories: '只沉淀通过回归验证的工程经验。', evaluation: '用可复现的结果，衡量调查与修复质量。', compare: '将两次真实调查并排，审阅证据、用量与结果差异。' }[view]

  return <div className="app-shell">
    {mobileNav && <div className="nav-backdrop" onClick={() => setMobileNav(false)}/>}
    <aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}>
      <a className="brand" href="#" onClick={event => { event.preventDefault(); navigate('runs') }}><span className="brand-mark"><Layers3 size={23} strokeWidth={2.2}/></span><div>TraceForge<span>ENGINEERING INTELLIGENCE</span></div></a>
      <div className="workspace-switch"><div className="workspace-avatar"><Command size={17}/></div><div><strong>本地工作空间</strong><span>Local workspace</span></div><ChevronDown size={14}/></div>
      <div className="nav-caption">工作空间</div>
      <nav>
        <button className={view === 'runs' ? 'active' : ''} onClick={() => navigate('runs')}><Activity size={18}/><span>调查工作台</span>{metrics && metrics.approval_pending > 0 && <b>{metrics.approval_pending}</b>}</button>
        <button className={view === 'projects' ? 'active' : ''} onClick={() => navigate('projects')}><FolderGit2 size={18}/><span>项目注册表</span><small>{projects.length || ''}</small></button>
        <button className={view === 'memories' ? 'active' : ''} onClick={() => navigate('memories')}><BookOpen size={18}/><span>知识记忆</span></button>
        <button className={view === 'evaluation' ? 'active' : ''} onClick={() => navigate('evaluation')}><FlaskConical size={18}/><span>评测中心</span></button>
        <button className={view === 'compare' ? 'active' : ''} onClick={() => navigate('compare')}><GitCompareArrows size={18}/><span>运行对比</span></button>
      </nav>
      <div className="sidebar-bottom"><div className="trust-card"><ShieldCheck size={19}/><strong>证据优先 · 源码只读</strong><p>每次修改都需审批，<br/>验证在独立快照中执行。</p><span><span className="live-dot"/>隔离执行边界</span></div><button className="settings-button" onClick={() => setModal('settings')}><Settings2 size={17}/><span>连接设置</span><span className={`connection-dot ${health && !connectionError ? 'connected' : ''}`}/></button><div className="sidebar-footer"><span>TRACEFORGE</span><span>{health ? `v${health.version}` : 'LOCAL FIRST'}</span></div></div>
    </aside>
    <main className="main-shell">
      <header className="topbar"><div className="breadcrumbs"><button className="icon-button mobile-menu" aria-label="打开导航" onClick={() => setMobileNav(true)}><Menu size={19}/></button><span>工作空间</span><ChevronRight size={13}/><strong>{title}</strong></div><div className="topbar-right"><span className="local-badge"><LockKeyhole size={11}/>LOCAL</span><span className={`connection-status ${health && !connectionError ? 'online' : 'offline'}`}><span/>{health && !connectionError ? '服务已连接' : loading ? '连接中' : '连接异常'}</span><button className="avatar" title="连接设置" onClick={() => setModal('settings')}>TF</button></div></header>
      <div className="main-content">
        <div className="page-heading"><div><div className="eyebrow">OBSERVE. REASON. VERIFY.</div><h1>{title}<span className="heading-dot">.</span></h1><p>{subtitle}</p></div><div className="page-actions">{view === 'runs' && <button className="button secondary" onClick={() => void startDemo()} disabled={!!busy}><Play size={15}/>{busy === 'demo' ? '创建回放中…' : '离线演示'}</button>}<button className="button primary" onClick={() => setModal(view === 'projects' ? 'project' : 'run')}><Plus size={17}/>{view === 'projects' ? '注册项目' : '新建调查'}</button></div></div>
        {(error || connectionError) && <div className="error-banner" role="alert"><XCircle size={18}/><span>{error || connectionError}</span><button onClick={() => { setRefreshTick(value => value + 1); setModal('settings') }}>连接设置</button><button className="icon-button" aria-label="关闭错误信息" onClick={() => { setError(''); setConnectionError('') }}><X size={16}/></button></div>}
        {view === 'runs' && <><div className="metrics-grid">
          <Metric title="调查总数" value={metrics?.total_runs} icon={<Activity size={18}/>} foot="所有持久化调查"/>
          <Metric title="已验证修复" value={metrics?.verified_fixes} icon={<CheckCheck size={19}/>} foot="基线失败 → 修复后通过" accent="green"/>
          <Metric title="等待审批" value={metrics?.approval_pending} icon={<GitPullRequest size={18}/>} foot="人工确认后应用补丁" accent="amber"/>
          <Metric title="模型调用" value={metrics?.provider_calls} icon={<Cpu size={18}/>} foot={metrics ? `${number(metrics.input_tokens + metrics.output_tokens)} tokens · 实际用量` : '等待服务数据'}/>
        </div><div className="workbench"><section className="run-browser"><div className="run-browser-heading"><h2>调查记录 <span>{runs.length}</span></h2><button className="icon-button" title="刷新数据" aria-label="刷新数据" onClick={() => setRefreshTick(value => value + 1)}><ListFilter size={16}/></button></div><label className="search-field"><Search size={15}/><input aria-label="搜索调查" placeholder="搜索调查或项目…" value={search} onChange={event => setSearch(event.target.value)}/><span>/</span></label><div className="run-filters"><button className={filter === 'all' ? 'selected' : ''} onClick={() => setFilter('all')}>全部</button><button className={filter === 'active' ? 'selected' : ''} onClick={() => setFilter('active')}>进行中</button><button className={filter === 'completed' ? 'selected' : ''} onClick={() => setFilter('completed')}>已完成</button></div><div className="run-list">{loading ? <Loading label="读取调查…"/> : visibleRuns.length ? visibleRuns.map(item => <button className={`run-item ${selectedId === item.id ? 'selected' : ''}`} key={item.id} onClick={() => { setSelectedId(item.id); setTab('overview') }}><div className="run-item-top"><span className="run-code">#{item.id.slice(0, 8)}</span><span>{date(item.created_at)}</span></div><h3>{item.title}</h3><div className="run-project"><FolderGit2 size={12}/>{projects.find(project => project.id === item.project_id)?.name || item.project_id}</div><div className="run-item-bottom"><Badge status={item.status}/><span className="mode-label">{modeLabels[item.mode]}</span></div></button>) : <div className="run-list-empty"><FileSearch size={25}/><span>{runs.length ? '没有匹配的调查' : '还没有调查记录'}</span><small>{runs.length ? '尝试其他关键词或筛选条件' : '创建调查，开始追踪问题'}</small></div>}</div><div className="run-browser-footer"><Radio size={12}/><span>每 2 秒同步调查状态</span></div></section>
          <section className="detail-panel">{detailLoading ? <Loading label="正在还原调查现场…"/> : detailError && !run ? <Empty icon={<Unplug size={28}/>} title="无法读取调查" action={<button className="button secondary" onClick={() => setRefreshTick(value => value + 1)}>重试</button>}>{detailError}</Empty> : run ? <>
            <div className="detail-heading"><div className="detail-kicker"><span className="mono">RUN / {run.id.slice(0, 12)}</span><span className={`mode-pill mode-${run.mode}`}><span/>{modeLabels[run.mode]}</span></div><div className="detail-title-row"><h2>{run.title}</h2><Badge status={run.status}/></div><div className="detail-meta"><span><FolderGit2 size={13}/>{selectedProject?.name || run.project_id}</span><span><Clock3 size={13}/>{date(run.created_at)}</span><span><ShieldCheck size={13}/>{selectedProject?.runner === 'local' ? '可信本地执行' : 'Docker 隔离'}</span></div></div>
            <ReportExport key={run.id} runId={run.id}/>
            <div className="detail-tabs" role="tablist" aria-label="调查详情">{([{ id: 'overview', label: '概览', icon: <Boxes size={14}/> }, { id: 'evidence', label: '证据', icon: <FileSearch size={14}/>, count: run.state.evidence?.length }, { id: 'patch', label: '修复方案', icon: <GitCompareArrows size={14}/>, count: run.state.diagnosis?.patches?.length }, { id: 'verification', label: '验证结果', icon: <Beaker size={14}/> }, { id: 'events', label: '执行轨迹', icon: <Terminal size={14}/> }] as { id: DetailTab; label: string; icon: ReactNode; count?: number }[]).map(item => <button role="tab" aria-selected={tab === item.id} className={tab === item.id ? 'active' : ''} key={item.id} onClick={() => setTab(item.id)}>{item.icon}{item.label}{!!item.count && <span>{item.count}</span>}</button>)}</div>
            <div className="detail-body">{detailError && <div className="inline-warning">{detailError}</div>}{run.error && <div className="inline-error"><XCircle size={16}/><span>{run.error}</span></div>}{run.mode === 'replay' && <div className="replay-note"><Play size={13}/><span>离线夹具回放 · 使用固定演示案例，未调用语言模型。</span></div>}
            {tab === 'overview' && <><Progress run={run}/><div className="question-block"><div className="section-label"><Terminal size={14}/>问题输入</div><p>{run.query}</p></div>{run.state.diagnosis ? <DiagnosisPanel status={run.status} diagnosis={run.state.diagnosis} evidence={run.state.evidence || []} onEvidence={() => setTab('evidence')} onPatch={() => setTab('patch')}/> : <div className="investigation-placeholder"><div className="investigation-symbol">{terminal.has(run.status) ? <Circle size={23}/> : <LoaderCircle className="spin" size={23}/>}</div><div><h3>{terminal.has(run.status) ? '调查已结束' : '正在收集与关联证据'}</h3><p>{terminal.has(run.status) ? '查看执行轨迹了解本次调查的完整过程。' : '代码检索、Git 上下文与诊断过程将持续记录到执行轨迹。'}</p></div></div>}{run.state.verification && <VerificationSummary verification={run.state.verification} onClick={() => setTab('verification')}/>}<RecentEvents events={events} onAll={() => setTab('events')}/></>}
            {tab === 'evidence' && <EvidencePanel evidence={run.state.evidence || []} diagnosis={run.state.diagnosis}/>}
            {tab === 'patch' && <PatchPanel patches={run.state.diagnosis?.patches || []} run={run} busy={busy} onEvidence={() => setTab('evidence')} onDecide={decide} onDownload={() => void action('download', () => downloadArtifact(run.id))}/>}
            {tab === 'verification' && <VerificationPanel verification={run.state.verification} status={run.status} onPatch={() => setTab('patch')} onDownload={() => void action('download', () => downloadArtifact(run.id))}/>}
            {tab === 'events' && <EventsPanel events={events} usage={run.state.usage}/>}
            </div><div className="detail-footer"><span><span className={!terminal.has(run.status) ? 'live-dot' : 'quiet-dot'}/>{terminal.has(run.status) ? '调查记录已保存' : '实时同步中'}<span className="footer-divider">/</span>更新于 {time(run.updated_at)}</span>{!terminal.has(run.status) && <button disabled={!!busy} onClick={() => void action('cancel', async () => setRun(await api<Run>(`/runs/${encodeURIComponent(run.id)}/cancel`, {})))}><Square size={11}/>{busy === 'cancel' ? '取消中…' : '取消调查'}</button>}</div>
          </> : <div className="welcome-state"><div className="welcome-grid"><div className="welcome-orbit"><div><Layers3 size={38} strokeWidth={1.6}/></div></div><span className="welcome-code code-a">evidence.collect()</span><span className="welcome-code code-b">patch.verify()</span></div><span className="eyebrow">YOUR NEXT INVESTIGATION STARTS HERE</span><h2>让每一次修复<br/>都有迹可循<span>.</span></h2><p>连接仓库，提交问题。TraceForge 将代码、变更与测试<br className="desktop-break"/>串联成可审阅的证据链。</p><div className="welcome-actions"><button className="button primary" onClick={() => setModal('run')}><Plus size={16}/>创建第一条调查</button><button className="button text-button" onClick={() => void startDemo()} disabled={!!busy}>运行离线演示<ArrowRight size={15}/></button></div><div className="welcome-steps"><span><Search size={15}/>检索证据</span><ChevronRight size={12}/><span><GitPullRequest size={15}/>审阅补丁</span><ChevronRight size={12}/><span><CheckCircle2 size={15}/>回归验证</span></div></div>}</section></div></>}
        {view === 'projects' && <section className="content-panel"><PanelTitle icon={<FolderGit2 size={19}/>} title="已连接的仓库" subtitle={`${projects.length} 个项目 · 原始仓库始终保持只读`} right={<span className="small-tag">PROJECT REGISTRY</span>}/>{loading ? <Loading/> : projects.length ? <div className="project-grid">{projects.map(project => <article className="project-card" key={project.id}><div className="project-card-heading"><div className="project-icon"><FolderGit2 size={23}/></div><span className={`runner-tag ${project.runner === 'local' ? 'local-runner' : ''}`}><ShieldCheck size={12}/>{project.runner === 'docker' ? 'Docker 隔离' : '可信本地'}</span></div><h3>{project.name}</h3><p className="project-path" title={project.root}>{project.root}</p><div className="project-command"><Terminal size={13}/><code>{project.test_command.join(' ')}</code></div><div className="project-card-meta"><span><GitBranch size={13}/>{project.github_repo || '仅本地代码'}</span><span>{date(project.created_at)}</span></div><button className="project-action" onClick={() => { setMemoryProject(project.id); setModal('run') }}>发起调查<ArrowUpRight size={15}/></button></article>)}</div> : <Empty icon={<FolderGit2 size={32}/>} title="连接你的第一个项目" action={<button className="button primary" onClick={() => setModal('project')}><Plus size={15}/>注册项目</button>}>注册本地路径和测试命令，为每次调查提供明确的代码与执行边界。</Empty>}<div className="boundary-note"><LockKeyhole size={16}/><div><strong>仓库访问边界</strong><p>项目路径必须位于后端 TRACEFORGE_ALLOWED_ROOTS 允许的目录内。当前允许：{health?.allowed_roots?.length ? health.allowed_roots.join(' · ') : '等待后端配置'}。修改此环境变量后需重启后端服务。</p></div></div></section>}
        {view === 'memories' && <section className="content-panel"><PanelTitle icon={<BookOpen size={19}/>} title="从验证中积累经验" subtitle="仅在基线失败、修复后测试通过时写入知识记忆" right={<select className="compact-select" aria-label="选择知识记忆项目" value={memoryProject} onChange={event => setMemoryProject(event.target.value)}>{!projects.length && <option value="">暂无项目</option>}{projects.map(project => <option key={project.id} value={project.id}>{project.name}</option>)}</select>}/>{extraLoading ? <Loading label="读取已验证经验…"/> : memories.length ? <div className="memory-list">{memories.map((memory, index) => <article className="memory-card" key={memory.id || `${memory.run_id}-${index}`}><span className="memory-icon"><CheckCheck size={20}/></span><div><div className="memory-meta"><span>VERIFIED KNOWLEDGE</span><time>{date(memory.created_at)}</time></div><p>{memory.summary}</p><div className="memory-citations">{memory.evidence_ids?.map(id => <code key={id}>{id.slice(0, 16)}</code>)}</div><button className="link-button" onClick={() => openRun(memory.run_id)}>查看来源调查 #{memory.run_id.slice(0, 8)}<ArrowUpRight size={13}/></button></div></article>)}</div> : <Empty icon={<BookOpen size={30}/>} title="知识从可靠的修复开始">这个项目还没有通过回归验证的修复记录。完成调查、审批补丁并通过验证后，经验将自动出现在这里。</Empty>}</section>}
        {view === 'compare' && <><div className="compare-toolbar"><span>所有比较数据均来自保存的调查记录</span><button className="button secondary small" onClick={() => setRefreshTick(value => value + 1)}><Activity size={13}/>刷新对比</button></div><ComparisonPanel runs={runs} projects={projects} refreshTick={refreshTick} onOpen={openRun}/></>}
        {view === 'evaluation' && <section className="content-panel"><div className="evaluation-switch"><button className={evaluationType === 'harness' ? 'active' : ''} onClick={() => setEvaluationType('harness')}><ShieldCheck size={14}/>执行链路评测</button><button className={evaluationType === 'benchmark' ? 'active' : ''} onClick={() => setEvaluationType('benchmark')}><FlaskConical size={14}/>多故障基准</button></div><PanelTitle icon={<FlaskConical size={19}/>} title="可复现的质量评测" subtitle="读取后端保存的真实评测报告" right={<button className="button secondary small" onClick={() => setRefreshTick(value => value + 1)}><Activity size={13}/>刷新报告</button>}/>{extraLoading ? <Loading label="读取评测报告…"/> : !evaluation || evaluation.available === false ? <Empty icon={<FlaskConical size={32}/>} title={evaluationType === 'benchmark' ? '还没有多故障基准报告' : '还没有评测报告'}>{evaluationType === 'benchmark' ? '多故障评测结果将从后端已保存的 benchmark 报告加载。完成一次基准评测后，点击刷新报告。' : '后端尚未保存评测结果。运行项目提供的评测命令后，在这里查看真实的执行结果与质量指标。'}</Empty> : evaluationType === 'benchmark' ? <BenchmarkReport report={evaluation}/> : <EvaluationReport report={evaluation}/>}</section>}
        <footer className="page-footer"><span><ShieldCheck size={12}/>本地优先 · 审批驱动 · 全程可追溯</span><span>TRACEFORGE / ENGINEERING WORKBENCH</span></footer>
      </div>
    </main>
    {modal === 'settings' && <SettingsModal health={health} onClose={closeModal} onSave={() => { setRefreshTick(value => value + 1); closeModal() }}/>}
    {modal === 'project' && <ProjectModal health={health} onClose={closeModal} onCreated={async project => { await refresh(); setMemoryProject(project.id); closeModal(); setView('projects') }}/>}
    {modal === 'run' && <RunModal projects={projects} health={health} defaultProject={memoryProject} onClose={closeModal} onRegister={() => setModal('project')} onCreated={async created => { await refresh(); setSelectedId(created.id); setTab('overview'); setView('runs'); closeModal() }}/>}
  </div>
}

function Metric({ title, value, icon, foot, accent = 'cyan' }: { title: string; value?: number; icon: ReactNode; foot: string; accent?: string }) { return <div className={`metric-card metric-${accent}`}><div className="metric-top"><span>{title}</span><div>{icon}</div></div><strong>{number(value)}</strong><div className="metric-foot"><span/>{foot}</div><span className="metric-decoration"/></div> }
function Progress({ run }: { run: Run }) {
  const stages = ['queued', 'investigating', 'awaiting_approval', 'verifying', 'completed']
  const labels = ['接收问题', '关联证据', '审阅方案', '执行验证', '完成归档']
  const current = stages.indexOf(run.status)
  return <div className="progress-track">{stages.map((stage, index) => {
    const completed = run.status === 'completed'
    const skipped = completed && ((index === 2 && !run.state.diagnosis?.patches?.length) || (index === 3 && !run.state.verification))
    const done = !skipped && (current > index || (completed && index === 4))
    const label = skipped ? index === 2 ? '无需补丁' : '未执行验证' : labels[index]
    return <div className={`progress-stage ${skipped ? 'skipped' : done ? 'done' : current === index ? 'current' : ''}`} key={stage}><div className="progress-node">{skipped ? <span>—</span> : done ? <Check size={12}/> : <span>{index + 1}</span>}</div><span>{label}</span></div>
  })}</div>
}
function CitationTags({ ids, evidence, onClick }: { ids: string[]; evidence: Evidence[]; onClick?: () => void }) { return <div className="citation-tags">{ids.map(id => { const item = evidence.find(entry => entry.id === id); return <button key={id} onClick={onClick} title={id}><FileCode2 size={12}/>{item ? `${item.path}:${item.line_start}` : id.slice(0, 16)}<ArrowUpRight size={11}/></button> })}</div> }
function DiagnosisPanel({ status, diagnosis, evidence, onEvidence, onPatch }: { status: string; diagnosis: Diagnosis; evidence: Evidence[]; onEvidence: () => void; onPatch: () => void }) { return <section className="diagnosis-card"><PanelTitle icon={<Sparkles size={17}/>} title="诊断阶段记录" right={<span className={`confidence confidence-${diagnosis.confidence}`}>置信度 · {{ high: '高', medium: '中', low: '低' }[diagnosis.confidence] || diagnosis.confidence}</span>}/><div className="diagnosis-content"><h3>{diagnosis.summary}</h3><p>{diagnosis.root_cause}</p><CitationTags ids={diagnosis.evidence_ids || []} evidence={evidence} onClick={onEvidence}/>{diagnosis.limitations?.length > 0 && <div className="limitations"><strong>边界与限制</strong>{diagnosis.limitations.map((item, index) => <p key={index}>{item}</p>)}</div>}</div>{diagnosis.patches?.length > 0 && <button className="diagnosis-patch-link" onClick={onPatch}><span><GitCompareArrows size={15}/>{diagnosis.patches.length} 处代码修改{status === 'awaiting_approval' ? '等待审阅' : ' · 查看方案'}</span><ArrowRight size={15}/></button>}</section> }
function RecentEvents({ events, onAll }: { events: TraceEvent[]; onAll: () => void }) { return <section className="recent-events"><PanelTitle title="最近活动" icon={<Activity size={15}/>} right={<button className="link-button" onClick={onAll}>完整轨迹<ArrowRight size={12}/></button>}/>{events.length ? events.slice(-4).reverse().map(event => <div className="recent-event" key={event.id}><span className="event-node"/><span className="recent-kind">{eventName(event.kind)}</span><span className="recent-event-summary">{eventSummary(event)}</span><time>{time(event.created_at)}</time></div>) : <p className="muted compact-empty">等待第一条持久化事件。</p>}</section> }
const eventNames: Record<string, string> = { status: '状态更新', status_changed: '状态更新', run_created: '调查创建', queued: '进入队列', investigation_started: '开始调查', retrieval: '证据检索', evidence: '证据收集', index: '建立索引', indexed: '索引已建立', diagnosis: '生成诊断', approval: '审批记录', approved: '补丁获批', verification: '回归验证', verification_started: '开始验证', completed: '调查完成', error: '执行异常', failed: '执行失败', provider_call: '模型调用', tool_call: '工具调用', checkpoint: '保存检查点', memory: '知识沉淀', cancelled: '调查取消' }
const auditEventNames: Record<string, string> = { 'run.created': '创建调查', 'run.status': '状态迁移', 'run.error': '执行异常', 'run.cancelled': '取消调查', 'retrieval.indexed': '索引已建立', 'specialist.started': '专家开始分析', 'specialist.completed': '专家分析完成', 'runtime.checkpoint': '保存检查点', 'replay.fixture': '离线夹具回放', 'diagnosis.ready': '诊断记录已生成', 'approval.decided': '审批已记录', 'verification.started': '开始执行测试', 'verification.result': '测试结果已保存', 'verification.completed': '验证已完成', 'investigation.retrieval_only': '仅检索调查', 'provider.request': '模型请求', 'provider.response': '模型响应', 'tool.call': '工具调用', 'tool.result': '工具结果', 'memory.saved': '知识已沉淀' }
function eventName(kind: string) { return auditEventNames[kind] || eventNames[kind] || kind.replaceAll('_', ' ').replaceAll('.', ' / ') }
function eventSummary(event: TraceEvent) {
  const p = event.payload
  if (p.from && p.to) return `${statusLabels[String(p.from)] || p.from} → ${statusLabels[String(p.to)] || p.to}`
  if (p.decision) return p.decision === 'approve' ? '批准此补丁，进入隔离验证' : '拒绝此补丁'
  if (p.status && statusLabels[String(p.status)]) return statusLabels[String(p.status)]
  const phaseLabels: Record<string, string> = { baseline: '原始基线', patched: '应用补丁后', retrieved: '证据检索完成', verifying: '隔离验证' }
  return String(p.message || p.summary || (p.phase ? phaseLabels[String(p.phase)] || p.phase : '') || p.tool || Object.entries(p).slice(0, 2).map(([key, value]) => `${key}: ${typeof value === 'object' ? JSON.stringify(value) : value}`).join(' · ') || '已记录')
}
function EvidencePanel({ evidence, diagnosis }: { evidence: Evidence[]; diagnosis?: Diagnosis }) { return <>{evidence.length ? <><div className="section-intro"><div><h3>可追溯的上下文</h3><p>每条证据保留来源、文件行号与内容摘要。</p></div><span className="small-tag">{evidence.length} SOURCES</span></div><div className="evidence-list">{evidence.map((item, index) => <details className="evidence-card" key={item.id} open={index < 3}><summary><span className="evidence-file-icon"><FileCode2 size={17}/></span><div><strong>{item.path || item.source}</strong><span>{item.source} · {item.line_start ? `L${item.line_start}–L${item.line_end}` : item.kind}</span></div>{diagnosis?.evidence_ids?.includes(item.id) && <span className="cited-tag">已引用</span>}<ChevronDown size={15}/></summary><div className="code-with-lines">{item.content.split('\n').map((line, lineIndex) => <div className="code-line" key={lineIndex}><span>{(item.line_start || 1) + lineIndex}</span><code>{line || ' '}</code></div>)}</div><div className="evidence-footer"><code title={item.id}>{item.id}</code><span>{item.kind}{Number.isFinite(item.score) ? ` · ${item.score.toFixed(3)}` : ''}</span></div></details>)}</div></> : <Empty icon={<FileSearch size={29}/>} title="证据尚未收集">调查开始后，实际检索到的代码、Git 记录和项目上下文会显示在这里。</Empty>}</> }
function PatchPanel({ patches, run, busy, onEvidence, onDecide, onDownload }: { patches: Patch[]; run: Run; busy: string; onEvidence: () => void; onDecide: (decision: 'approve' | 'reject') => unknown; onDownload: () => void }) { if (!patches.length) return <Empty icon={<GitCompareArrows size={30}/>} title="当前没有待应用补丁">诊断可以仅提供证据与解释。只有生成了明确的代码修改，才会进入审批流程。</Empty>; return <><div className="section-intro"><div><h3>审阅代码修改</h3><p>精确替换 · {patches.length} 处修改 · 仅应用到隔离快照</p></div>{run.state.verification?.artifact_path && <button className="button secondary small" onClick={onDownload}><ArrowDownToLine size={13}/>下载 .patch</button>}</div>{patches.map((patch, index) => <article className="patch-card" key={`${patch.path}-${index}`}><div className="patch-file"><FileCode2 size={16}/><strong>{patch.path}</strong><span className="diff-count"><b>+{patch.after.split('\n').length}</b><i>−{patch.before.split('\n').length}</i></span></div><div className="patch-reason">{patch.reason}</div><div className="diff-code">{patch.before.split('\n').map((line, lineIndex) => <div className="diff-line removed" key={`old-${lineIndex}`}><span>−</span><code>{line || ' '}</code></div>)}{patch.after.split('\n').map((line, lineIndex) => <div className="diff-line added" key={`new-${lineIndex}`}><span>+</span><code>{line || ' '}</code></div>)}</div><div className="patch-citations"><CitationTags ids={patch.evidence_ids || []} evidence={run.state.evidence || []} onClick={onEvidence}/></div></article>)}{run.status === 'awaiting_approval' ? <div className="approval-card"><div className="approval-heading"><ShieldCheck size={21}/><div><h3>由你决定下一步</h3><p>审批后，在独立快照中运行基线测试、应用补丁并执行回归测试。</p></div></div><div className="digest-line"><LockKeyhole size={12}/><span>绑定补丁 SHA256</span><code title={run.state.patch_digest}>{run.state.patch_digest || '等待补丁摘要…'}</code></div><div className="approval-actions"><button className="button danger-quiet" disabled={!!busy || !run.state.patch_digest} onClick={() => onDecide('reject')}><X size={15}/>{busy === 'reject' ? '拒绝中…' : '拒绝方案'}</button><button className="button primary" disabled={!!busy || !run.state.patch_digest} onClick={() => onDecide('approve')}>{busy === 'approve' ? <LoaderCircle size={15} className="spin"/> : <Check size={16}/>}批准并验证</button></div></div> : <div className="patch-state"><ShieldCheck size={16}/>{run.status === 'verifying' ? '审批已记录，正在独立快照中执行验证。' : run.status === 'rejected' ? '此方案已被拒绝，未应用补丁。' : run.status === 'completed' ? '调查已完成，补丁与审批记录已归档。' : '当前状态不可审批。查看执行轨迹了解详情。'}</div>}</> }
function VerificationSummary({ verification, onClick }: { verification: Verification; onClick: () => void }) {
  const verified = isVerified(verification)
  return <button className={`verification-summary ${verified ? 'verified' : ''}`} onClick={onClick}><span className="verification-summary-icon">{verified ? <CheckCheck size={21}/> : <Beaker size={21}/>}</span><div><strong>{verified ? '回归已修复，证据链闭环' : '测试执行记录已保存'}</strong><span>基线 exit {verification.baseline?.exit_code ?? '—'}<ArrowRight size={12}/>修复后 exit {verification.patched?.exit_code ?? '—'}</span></div><ArrowUpRight size={17}/></button>
}
function TestOutput({ result, label, version }: { result?: TestResult; label: string; version: string }) {
  const tests = result?.tests
  const zeroTests = tests?.executed === 0
  const passed = result?.exit_code === 0 && !zeroTests
  return <section className="test-output"><div className="test-output-header"><div><span>{version}</span><h3>{label}</h3></div>{result ? <span className={`test-status ${zeroTests ? 'test-no-cases' : passed ? 'test-passed' : 'test-failed'}`}>{passed ? <CheckCircle2 size={13}/> : <XCircle size={13}/>}{result.timed_out ? '超时' : zeroTests ? '未运行测试' : passed ? '通过' : '失败'}</span> : <span className="small-tag">尚未执行</span>}</div><div className="test-meta"><span>EXIT CODE <b>{result?.exit_code ?? '—'}</b></span><span>DURATION <b>{result?.duration_ms === undefined ? '—' : `${(result.duration_ms / 1000).toFixed(2)}s`}</b></span></div>{tests ? <><div className="test-counts"><div><strong>{tests.executed}</strong><span>实际执行</span></div><div className="count-pass"><strong>{tests.passed}</strong><span>通过</span></div><div className={tests.failed > 0 ? 'count-fail' : ''}><strong>{tests.failed}</strong><span>失败</span></div><div><strong>{tests.skipped}</strong><span>跳过</span></div></div><div className="test-framework">解析框架 <code>{tests.framework}</code></div></> : <div className="test-counts-unavailable">{result ? '未解析测试数量 · 请审阅原始输出' : '实际测试数量将在执行后显示'}</div>}<pre>{result ? [result.stdout?.trim(), result.stderr?.trim()].filter(Boolean).join('\n\n[stderr]\n') || '进程没有输出。' : '等待执行测试命令…'}</pre></section>
}
function VerificationPanel({ verification, status, onPatch, onDownload }: { verification?: Verification; status: string; onPatch: () => void; onDownload: () => void }) {
  if (!verification) return <Empty icon={status === 'verifying' ? <LoaderCircle className="spin" size={30}/> : <Beaker size={31}/>} title={status === 'verifying' ? '正在隔离快照中验证' : '等待回归验证'} action={status === 'awaiting_approval' ? <button className="button primary" onClick={onPatch}>审阅修复方案<ArrowRight size={15}/></button> : undefined}>{status === 'verifying' ? '依次执行基线测试、应用已批准的补丁、执行修复后测试。结果将自动更新。' : '先审阅并批准修复方案，再比较基线与修复后的真实测试结果。'}</Empty>
  const verified = isVerified(verification)
  const limitations = verificationLimitations(verification)
  return <><div className={`verification-result ${verified ? 'result-pass' : 'result-neutral'}`}><div>{verified ? <CheckCheck size={25}/> : <Beaker size={25}/>}</div><section><h3>{verified ? '回归修复已验证' : '尚未证明回归已修复'}</h3><p>{verified ? '基线测试失败，应用补丁后测试通过。该结果已形成可追溯验证记录。' : '实际运行测试、基线失败且修复后通过，才能认定回归修复；零测试或两次均通过不构成修复证明。'}</p>{verification.confidence && <span className="verification-confidence">验证置信度 · {{ high: '高', medium: '中', low: '低' }[verification.confidence] || verification.confidence}</span>}</section><span className="small-tag">{verification.runner || '隔离执行'}</span></div><div className="test-comparison"><TestOutput result={verification.baseline} label="原始基线" version="BASELINE"/><TestOutput result={verification.patched} label="应用补丁后" version="PATCHED"/></div>{limitations.length > 0 && <div className="verification-limitations"><div><ShieldCheck size={15}/><strong>验证边界与已知限制</strong></div>{limitations.map((item, index) => <p key={index}>{item}</p>)}</div>}{verification.diff && <section className="final-diff"><PanelTitle icon={<GitCompareArrows size={16}/>} title="最终补丁" right={verification.artifact_path ? <button className="button secondary small" onClick={onDownload}><ArrowDownToLine size={13}/>下载</button> : undefined}/><pre>{verification.diff.split('\n').map((line, index) => <span key={index} className={line.startsWith('+') ? 'diff-added-text' : line.startsWith('-') ? 'diff-removed-text' : line.startsWith('@@') ? 'diff-hunk-text' : ''}>{line}{'\n'}</span>)}</pre></section>}</>
}
function EventsPanel({ events, usage }: { events: TraceEvent[]; usage?: Record<string, unknown> }) { return <><div className="section-intro"><div><h3>完整执行轨迹</h3><p>状态迁移、工具调用与人工决策，均来自持久化审计记录。</p></div><span className="small-tag">{events.length} EVENTS</span></div>{usage && Object.keys(usage).length > 0 && <details className="usage-details"><summary><Cpu size={14}/>实际模型用量<ChevronDown size={13}/></summary><pre>{JSON.stringify(usage, null, 2)}</pre></details>}{events.length ? <div className="event-timeline">{events.map(event => <details className="timeline-event" key={event.id}><summary><span className={`timeline-dot ${event.kind.includes('error') || event.kind.includes('fail') ? 'timeline-error' : ''}`}/><span className="timeline-sequence">{String(event.id).padStart(3, '0')}</span><div><strong>{eventName(event.kind)}</strong><span>{eventSummary(event)}</span></div><time>{time(event.created_at)}</time><ChevronDown size={13}/></summary><pre>{JSON.stringify(event.payload, null, 2)}</pre></details>)}</div> : <Empty icon={<Terminal size={28}/>} title="等待执行事件">调查开始后，每个关键步骤都会在这里留下可审阅的记录。</Empty>}</> }

function EvaluationReport({ report }: { report: Record<string, unknown> }) {
  const cases = Array.isArray(report.cases) ? report.cases as { name: string; category: string; passed: boolean; detail: unknown; duration_ms?: number }[] : []
  const total = typeof report.total_cases === 'number' ? report.total_cases : undefined
  const passed = typeof report.passed_cases === 'number' ? report.passed_cases : undefined
  const rate = typeof report.pass_rate === 'number' ? report.pass_rate : undefined
  const limitations = Array.isArray(report.limitations) ? report.limitations.map(String) : []
  return <div className="evaluation-report"><div className="report-heading"><FlaskConical size={22}/><div><h3>{report.kind === 'offline-harness' ? '离线执行链路评测' : '已保存的评测报告'}</h3><p>{report.kind === 'offline-harness' ? '验证系统边界与执行链路；不代表真实模型的诊断效果。' : '所有结果均来自后端持久化报告。'}{typeof report.generated_at === 'string' && ` · ${date(report.generated_at)}`}</p></div><span className="small-tag">{String(report.kind || 'EVALUATION')}</span></div>{total !== undefined && <div className="evaluation-metrics"><div><span>评测用例</span><strong>{number(total)}</strong></div><div><span>通过用例</span><strong>{number(passed)}</strong></div><div><span>通过率</span><strong>{rate === undefined ? '—' : `${(rate * 100).toFixed(0)}%`}</strong></div></div>}{cases.length > 0 && <div className="evaluation-table"><div className="evaluation-table-head"><span>评测用例 / 分类</span><span>结果</span><span>耗时</span></div>{cases.map((item, index) => <details key={`${item.name}-${index}`} className="evaluation-case"><summary><div><strong>{item.name}</strong><small>{item.category}</small></div><span className={`test-status ${item.passed ? 'test-passed' : 'test-failed'}`}>{item.passed ? <CheckCircle2 size={12}/> : <XCircle size={12}/>}{item.passed ? '通过' : '失败'}</span><span className="evaluation-duration">{item.duration_ms === undefined ? '—' : `${(item.duration_ms / 1000).toFixed(2)}s`}<ChevronDown size={11}/></span></summary><pre>{typeof item.detail === 'string' ? item.detail : JSON.stringify(item.detail, null, 2)}</pre></details>)}</div>}{limitations.length > 0 && <div className="evaluation-limitations"><strong>评测边界</strong>{limitations.map((item, index) => <p key={index}>{item}</p>)}</div>}<details className="raw-report"><summary><BracesIcon/>查看完整原始报告<ChevronDown size={13}/></summary><pre className="json-report">{JSON.stringify(report, null, 2)}</pre></details></div>
}
function BracesIcon() { return <span className="mono">{'{ }'}</span> }

function SettingsModal({ health, onClose, onSave }: { health: Health | null; onClose: () => void; onSave: () => void }) {
  const [token, setToken] = useState(() => sessionStorage.getItem(TOKEN_KEY) || '')
  return <Modal title="连接设置" subtitle="凭证仅保存在当前浏览器会话中。" onClose={onClose}><form onSubmit={event => { event.preventDefault(); if (token.trim()) sessionStorage.setItem(TOKEN_KEY, token.trim()); else sessionStorage.removeItem(TOKEN_KEY); onSave() }}><label className="form-field">API Token<input type="password" autoComplete="off" value={token} onChange={event => setToken(event.target.value)} placeholder="后端未启用鉴权时可留空"/><small>与后端 TRACEFORGE_API_TOKEN 保持一致，使用 Authorization 请求头发送。</small></label><div className="settings-summary"><div><span>API 服务</span><code>同源 /api</code></div><div><span>模型提供方</span><strong>{health?.provider.configured ? '已配置' : '未配置'}</strong></div><div><span>模型</span><code>{health?.provider.model || '—'}</code></div><div><span>API 协议</span><code>{health?.provider.api_style || '—'}</code></div><div><span>Docker</span><strong>{health?.capabilities.docker_available ? '可用' : '不可用'}</strong></div></div><p className="form-note"><LockKeyhole size={14}/>模型 API 密钥仅通过后端环境变量配置，浏览器不会读取或保存。</p><div className="modal-actions"><button type="button" className="button secondary" onClick={onClose}>取消</button><button className="button primary" type="submit"><Check size={15}/>保存并连接</button></div></form></Modal>
}
function ProjectModal({ health, onClose, onCreated }: { health: Health | null; onClose: () => void; onCreated: (project: Project) => Promise<void> }) {
  const [name, setName] = useState(''); const [root, setRoot] = useState(''); const [command, setCommand] = useState('["python", "-m", "pytest", "-q"]'); const [runner, setRunner] = useState<'docker' | 'local'>('docker'); const [trusted, setTrusted] = useState(false); const [github, setGithub] = useState(''); const [error, setError] = useState(''); const [saving, setSaving] = useState(false)
  async function submit(event: FormEvent) {
    event.preventDefault(); setError('')
    let argv: unknown
    try { argv = JSON.parse(command) } catch { setError('测试命令必须是合法的 JSON 字符串数组，例如 ["python", "-m", "pytest"]。'); return }
    if (!Array.isArray(argv) || !argv.length || !argv.every(item => typeof item === 'string' && item.trim())) { setError('测试命令需要非空的字符串数组，每个参数独立填写，不经过 shell 执行。'); return }
    if (runner === 'local' && !trusted) { setError('本地执行需要明确确认该仓库及测试命令可信。'); return }
    setSaving(true)
    try { const project = await api<Project>('/projects', { name: name.trim(), root: root.trim(), test_command: argv, runner, trusted, github_repo: github.trim() || null }); await onCreated(project) } catch (err) { setError(errorMessage(err)) } finally { setSaving(false) }
  }
  return <Modal title="注册本地项目" subtitle="为调查指定代码来源与测试执行方式。" onClose={onClose} wide><form onSubmit={event => void submit(event)}><div className="form-row"><label className="form-field">项目名称<input required maxLength={100} value={name} onChange={event => setName(event.target.value)} placeholder="例如 checkout-service"/></label><label className="form-field">GitHub 仓库 <span className="optional">可选</span><input value={github} onChange={event => setGithub(event.target.value)} placeholder="owner/repository" pattern="[^/\s]+/[^/\s]+"/><small>填写后启用只读 issue 与 workflow 证据采集。</small></label></div><label className="form-field">本地仓库绝对路径<input required value={root} onChange={event => setRoot(event.target.value)} placeholder="D:\project\my-service"/><small>必须位于 TRACEFORGE_ALLOWED_ROOTS 内；如被拒绝，请在后端环境变量中添加父目录并重启服务。</small></label><div className="allowed-roots"><LockKeyhole size={13}/><span>允许目录：{health?.allowed_roots?.join(' · ') || '尚未读取，请检查服务连接'}</span></div><label className="form-field">测试命令 <span className="optional">ARGV / JSON</span><textarea className="mono" rows={2} required value={command} onChange={event => setCommand(event.target.value)}/><small>每个命令参数作为独立字符串，不使用 shell 管道或命令拼接。</small></label><div className="form-field">执行环境<div className="runner-options"><button type="button" className={runner === 'docker' ? 'selected' : ''} onClick={() => setRunner('docker')}><Boxes size={19}/><strong>Docker 隔离</strong><span>默认 · 无网络容器执行</span>{runner === 'docker' && <Check size={15}/>}</button><button type="button" className={runner === 'local' ? 'selected' : ''} onClick={() => setRunner('local')}><Terminal size={19}/><strong>可信本地</strong><span>仅用于明确可信的仓库</span>{runner === 'local' && <Check size={15}/>}</button></div></div>{runner === 'docker' && health && !health.capabilities.docker_available && <div className="inline-warning">当前服务未检测到 Docker。可先注册项目；执行验证前需要安装并启动 Docker，系统不会自动切换为本地执行。</div>}{runner === 'local' && <label className="checkbox-field"><input type="checkbox" checked={trusted} onChange={event => setTrusted(event.target.checked)}/><span>我确认此仓库及其测试命令可信，允许在本机的独立快照中执行。</span></label>}{error && <div className="inline-error" role="alert"><XCircle size={15}/><span>{error}</span></div>}<div className="modal-actions"><button type="button" className="button secondary" onClick={onClose}>取消</button><button type="submit" className="button primary" disabled={saving}>{saving ? <LoaderCircle className="spin" size={15}/> : <Plus size={15}/>}{saving ? '注册中…' : '注册项目'}</button></div></form></Modal>
}
function RunModal({ projects, health, defaultProject, onClose, onRegister, onCreated }: { projects: Project[]; health: Health | null; defaultProject: string; onClose: () => void; onRegister: () => void; onCreated: (run: Run) => Promise<void> }) {
  const [project, setProject] = useState(defaultProject || projects[0]?.id || ''); const [title, setTitle] = useState(''); const [query, setQuery] = useState(''); const [mode, setMode] = useState<'live' | 'investigate'>(health?.provider.configured ? 'live' : 'investigate'); const [error, setError] = useState(''); const [saving, setSaving] = useState(false)
  async function submit(event: FormEvent) { event.preventDefault(); setSaving(true); setError(''); try { await onCreated(await api<Run>('/runs', { project_id: project, title: title.trim(), query: query.trim(), mode })) } catch (err) { setError(errorMessage(err)) } finally { setSaving(false) } }
  return <Modal title="发起一次调查" subtitle="描述问题与观测到的现象，让证据带领调查。" onClose={onClose} wide>{projects.length ? <form onSubmit={event => void submit(event)}><label className="form-field">目标项目<select required value={project} onChange={event => setProject(event.target.value)}>{projects.map(item => <option value={item.id} key={item.id}>{item.name} · {item.runner}</option>)}</select></label><label className="form-field">调查标题<input value={title} onChange={event => setTitle(event.target.value)} required maxLength={200} placeholder="例如：优惠金额计算导致结账测试失败"/></label><label className="form-field">问题描述 / 错误日志<textarea rows={6} value={query} onChange={event => setQuery(event.target.value)} required placeholder={'发生了什么？预期结果是什么？\n粘贴相关错误日志、堆栈或复现步骤。'}/></label><div className="form-field">调查模式<div className="runner-options"><button type="button" className={mode === 'live' ? 'selected' : ''} disabled={!health?.provider.configured} onClick={() => setMode('live')}><Sparkles size={18}/><strong>模型调查</strong><span>{health?.provider.configured ? '证据推理与补丁建议' : '请先配置后端模型凭证'}</span>{mode === 'live' && <Check size={15}/>}</button><button type="button" className={mode === 'investigate' ? 'selected' : ''} onClick={() => setMode('investigate')}><Search size={18}/><strong>证据检索</strong><span>真实检索，无模型调用</span>{mode === 'investigate' && <Check size={15}/>}</button></div></div>{error && <div className="inline-error" role="alert"><XCircle size={15}/><span>{error}</span></div>}<div className="modal-actions"><span className="form-footer-note"><ShieldCheck size={13}/>原始仓库只读</span><button type="button" className="button secondary" onClick={onClose}>取消</button><button type="submit" className="button primary" disabled={saving}>{saving ? <LoaderCircle className="spin" size={15}/> : <ArrowRight size={15}/>}{saving ? '创建中…' : '开始调查'}</button></div></form> : <Empty icon={<FolderGit2 size={30}/>} title="先连接一个项目" action={<button className="button primary" onClick={onRegister}><Plus size={15}/>注册项目</button>}>注册仓库路径和测试命令后，即可针对实际代码发起调查。也可以关闭窗口，运行离线演示。</Empty>}</Modal>
}
